import '@kerfjs/ui/layout.css';

import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { delegate, signal } from 'kerfjs';

type WorkspaceView = 'board' | 'list' | 'timeline';

export function createWorkspaceViewControl(root: HTMLElement) {
  const stored = localStorage.getItem('workspace.view');
  const view = signal<WorkspaceView>(stored === 'board' || stored === 'timeline' ? stored : 'list');

  const render = () => <Toolbar label="Workspace toolbar" center={<ToolbarControlGroup label="Workspace view" appearance="borderless"><SegmentedControl id="workspace-view" label="Workspace view" value={view.value} action="set-workspace-view" appearance="toolbar" size="small" choices={[{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }]} /></ToolbarControlGroup>} />;

  const dispose = delegate(root, 'click', '[data-action="set-workspace-view"]', (_event, element) => {
    const next = element.dataset.segmentValue as WorkspaceView | undefined;
    if (!next || next === view.value) return;
    view.value = next;
    localStorage.setItem('workspace.view', next);
    root.dispatchEvent(new CustomEvent('workspace-view-change', { bubbles: true, detail: { value: next } }));
  });

  return { render, value: view, dispose };
}
